508	// Only local presence counts — remote-tracking presence is not enough. For the
509	// git-branch backend, if only the remote-tracking ref exists, a subsequent
510	// WriteCommitted creates a brand-new orphan local branch with an empty tree,
511	// which would clobber the remote on push.
512	//
513	// Fast path: check local storage directly — no network. If missing, fetch from
514	// the remote (the whole v1 branch for git-branch, or just this checkpoint's ref
515	// for git-refs) and re-check. Returns a possibly-freshly-opened repo handle so
516	// go-git sees any newly fetched refs/packfiles.
517	func ensureCheckpointAvailable(ctx, logCtx context.Context, repo *git.Repository, refs cpkg.PersistentRefs, checkpointID id.CheckpointID, isExistingCheckpoint bool) (*git.Repository, error) {
518		if !isExistingCheckpoint {
519			return repo, nil
520		}
521	
522		cfg, err := settings.LoadCheckpointsConfig(ctx)
523		if err != nil {
524			return repo, fmt.Errorf("resolve checkpoints config: %w", err)
525		}
526		primaryIsRefs := cpkg.PrimaryIsRefs(cfg)
527	
528		present, readErr := checkpointPresentLocally(ctx, repo, refs, checkpointID, primaryIsRefs)
529		if readErr != nil {
530			return repo, fmt.Errorf("failed to read checkpoint %s: %w", checkpointID, readErr)
531		}
532		if present {
533			return repo, nil
534		}
535	
536		// Missing locally — fetch from the remote, then re-check.
537		freshRepo, fetchErr := refreshCheckpoint(ctx, checkpointID, primaryIsRefs)
538		if fetchErr != nil {
539			logging.Warn(logCtx, "failed to refresh checkpoint metadata before attach; proceeding with local state",
540				slog.String("error", fetchErr.Error()))
541		} else {
542			repo = freshRepo
543			present, readErr = checkpointPresentLocally(ctx, repo, refs, checkpointID, primaryIsRefs)
544			if readErr != nil {
545				return repo, fmt.Errorf("failed to read checkpoint %s after refresh: %w", checkpointID, readErr)
546			}
547			if present {
548				return repo, nil
549			}
550		}
551	
552		return repo, missingCheckpointError(logCtx, checkpointID, primaryIsRefs)
553	}
