555	// refreshCheckpoint fetches the checkpoint referenced by HEAD from the remote and
556	// returns a freshly-opened repo so go-git sees the newly-fetched refs/packfiles.
557	// The fetch is backend-aware: git-refs fetches just this checkpoint's ref, while
558	// git-branch fetches the whole v1 metadata branch (the resume-equivalent chain).
559	func refreshCheckpoint(ctx context.Context, checkpointID id.CheckpointID, primaryIsRefs bool) (*git.Repository, error) {
560		if !primaryIsRefs {
561			_, repo, err := getMetadataTree(ctx)
562			return repo, err
563		}
564		refName, err := cpkg.RefName(checkpointID)
565		if err != nil {
566			return nil, fmt.Errorf("resolve checkpoint ref for %s: %w", checkpointID, err)
567		}
568		if err := FetchCheckpointRef(ctx, refName); err != nil {
569			return nil, err
570		}
571		repo, err := openRepository(ctx)
572		if err != nil {
573			return nil, fmt.Errorf("reopen repository after checkpoint ref fetch: %w", err)
574		}
575		return repo, nil
576	}
