578	// checkpointPresentLocally reports whether the checkpoint already exists locally
579	// under the configured primary store. It reads local-only; the caller's refresh
580	// path is responsible for any remote fetch.
581	//
582	// For the git-branch backend the checkpoint lives in the v1 branch tree, and the
583	// store would bootstrap a missing local branch from origin's remote-tracking ref
584	// (PrimaryAsRead makes reads origin-bootstrappable). Counting that would let a
585	// WriteCommitted create a fresh orphan local branch and clobber the remote on
586	// push, so gate on the local Primary ref existing first. For the git-refs backend
587	// the checkpoint lives at its own ref (the v1 branch is irrelevant) and the store
588	// read here is already local-only — attach wires no ref fetcher — so read it
589	// directly.
590	func checkpointPresentLocally(ctx context.Context, repo *git.Repository, refs cpkg.PersistentRefs, checkpointID id.CheckpointID, primaryIsRefs bool) (bool, error) {
591		if !primaryIsRefs {
592			if _, err := repo.Reference(refs.Primary, true); err != nil {
593				return false, nil //nolint:nilerr // Missing local branch is the "absent" signal, not an error.
594			}
595		}
596		store, err := openAttachStore(ctx, repo, refs.PrimaryAsLocalRead())
597		if err != nil {
598			return false, err
599		}
600		summary, err := store.Read(ctx, checkpointID)
601		if err != nil {
602			return false, err //nolint:wrapcheck // Caller wraps with checkpoint ID context
603		}
604		return summary != nil, nil
