			wantTarget:    "https://github.com/acme/checkpoints.git",
			checkpointRef: true,
		},
		{
			name:       "legacy branch falls back to origin on election failure",
			settings:   `{"enabled":true,"strategy_options":{"checkpoint_push_remote":"missing"}}`,
			wantTarget: "https://github.com/acme/source.git",
		},
		{
			name:          "checkpoint ref falls back to origin on election failure",
			settings:      `{"enabled":true,"strategy_options":{"checkpoint_push_remote":"missing"}}`,
			wantTarget:    "https://github.com/acme/source.git",
