	if !force {
		if !interactive.CanPromptInteractively() {
			// Non-interactive: can't prompt, print trailer for manual use.
			fmt.Fprintf(w, "\nCopy to your commit message to attach:\n\n  Entire-Checkpoint: %s\n", checkpointIDStr)
