func TestResolveAndValidateTranscript_LocalOnlyDoesNotFetch(t *testing.T) {
	setupAttachTestRepo(t)

	baseAgent, err := agent.Get(agent.AgentNameClaudeCode)
	if err != nil {
		t.Fatal(err)
	}
	ag := &failingTranscriptFetcher{
