func TestResolveAndValidateTranscript_FallbackWinsAfterFetchFailure(t *testing.T) {
	setupAttachTestRepo(t)

	const sessionID = "test-fetch-fallback"
	baseAgent, err := agent.Get(agent.AgentNameClaudeCode)
	if err != nil {
		t.Fatal(err)
